function weed(cands,seen,check){
  var out=[];
  cands.forEach(function(r){var v=check(r);if(v.ok&&!seen[r.id]){seen[r.id]=1;out.push(r);}});
  return out;}
var cands=[];for(var i=1;i<=10;i++)cands.push({id:'w'+(i%7),v:i});
var kept=weed(cands,{},function(r){return r.v%2===0?{ok:true,errors:[]}:{ok:false,errors:['odd']};});
assert(kept.length===3,'weeded 10 candidates to 3 (even v, unique ids: w2,w4,w6)');
log('weed-out: 10 candidates -> '+kept.length+' survivors');

function passN(cands,strict){
  return cands.filter(function(r){return strict?r.score>=80:r.score>=50;});}
var cands=[];for(var i=1;i<=10;i++)cands.push({id:'f'+i,score:i*10});
var p1=passN(cands,false), p2=passN(cands,true);
assert(p1.length===6&&p2.length===3,'pass1 keeps 6, pass2 keeps 3');
assert(p2.length<p1.length,'strictness ratchets up');
log('fine-tune: pass1='+p1.length+' pass2='+p2.length+' (ratchet confirmed)');

