  known[r.id]=1;return {ok:true,errors:[]};}});
reg.generate(1,function(){return {id:'JAH-X-000002'};});
var threw=false;
try{reg.generate(2,function(){return {id:'JAH-X-000001'};});}catch(e){threw=/CORRECTNESS_FAILED/.test(e.message);}
