var fails=0,halted=false;
function guarded(reg,seed,prod){
  if(halted)throw new Error('HALTED: suspicion threshold tripped');
  try{return reg.generate(seed,prod);}catch(e){fails++;if(fails>=3)halted=true;throw e;}}
var reg=G.SigRegCreate({check:function(){return {ok:false,errors:['bad']};}});
for(var i=0;i<3;i++){try{guarded(reg,i,function(){return {};});}catch(e){}}
assert(halted===true,'breaker tripped after 3 failures');
var blocked=false;
try{guarded(reg,9,function(){return {id:'x'};});}catch(e){blocked=/HALTED/.test(e.message);}
assert(blocked,'generation halted until review');
log('pause-on-suspicion: breaker tripped, generation halted');

function canary(seeds,check){
  var batch=seeds.map(function(s){return {id:'c'+s,ok:s!==3};});
  var bad=batch.filter(function(r){return !check(r).ok;});
  return bad.length?{shipped:false,batch:[]}:{shipped:true,batch:batch};}
var res=canary([1,2,3,4,5],function(r){return r.ok?{ok:true,errors:[]}:{ok:false,errors:['bad seed 3']};});
assert(res.shipped===false&&res.batch.length===0,'tainted batch discarded whole');
var res2=canary([1,2,4,5],function(){return {ok:true,errors:[]};});
assert(res2.shipped===true&&res2.batch.length===4,'clean batch ships');
log('canary: tainted batch discarded, clean batch shipped');

